function render(){if(!project)return;projectName.textContent=project.name;projectName.title=project.outputSpec?`${project.name} · ${project.outputSpec.name} · ${project.outputSpec.width} × ${project.outputSpec.height} ${project.outputSpec.unit}`:project.name;for(const b of [dsTop,dsChoice]){b.textContent=ds()?.name||'Design System';b.title='画布 DS：'+(ds()?.name||'未选择');b.setAttribute('aria-label','选择画布 DS')}$('#canvas').dataset.projectId=project.id;$('#canvas').dataset.designSystemId=ds()?.id||'';renderAssets();renderHistory();renderLog();safe(renderVisual)();send.disabled=!!job||pending;}
