   const updated=await D.transitionCanvasVersion(id,v.id,phase==='convert'?'converting':'generating',{...result,status:phase==='convert'?'ready':'concept',phase,error:null});if(job!==ticket||project?.id!==id)return;project=updated;mode='2d';render();
