async function chooseProject(){const records=await D.canvasProjects(),list=openModal('Project'),search=el('input');search.type='search';search.placeholder='搜索项目';search.setAttribute('aria-label','搜索项目');const results=el('div');list.append(search,results);function paint(){results.replaceChildren();for(const p of [...records].sort((a,b)=>b.modified-a.modified).filter(p=>p.name.toLowerCase().includes(search.value.toLowerCase()))){results.append(button(p.name,async()=>{modal.close();await openProject(p.id)},'cw-choice','folder'))}if(!results.children.length)results.append(el('p','暂无匹配项目'));icons()}search.oninput=paint;paint()}
const recent=el('div',undefined,'cw-recent-projects');$('.sidebar .nav').after(recent);
async function renderRecentProjects(){const list=await D.canvasProjects();recent.replaceChildren();if(list.length){const title=el('div',undefined,'cw-recent-title');title.append(el('span','最近项目'),ib('搜索项目','search',chooseProject));recent.append(title);for(const p of [...list].sort((a,b)=>b.modified-a.modified).slice(0,12)){const b=button(p.name,()=>openProject(p.id),'cw-recent-project','folder');b.title=p.name;b.setAttribute('aria-current',project?.id===p.id&&location.hash==='#canvas'?'page':'false');recent.append(b)}}icons()}
async function chooseChatHistory(){if(!project)return;const id=project.id,list=openModal('历史对话'),search=el('input');search.type='search';search.placeholder='搜索当前项目对话';search.setAttribute('aria-label','搜索历史对话');const results=el('div');list.append(search,results);const requests=[...project.requests].reverse();const paint=()=>{results.replaceChildren();for(const r of requests.filter(r=>r.prompt.toLowerCase().includes(search.value.toLowerCase()))){const b=button('',async()=>{if(project?.id!==id)return;if(job||switching)return notify('请先等待或取消当前任务');modal.close();if(r.versionId){await savePatch({currentVersion:r.versionId,viewMode:'2d'});mode='2d';render()}setChat('expanded');requestAnimationFrame(()=>log.querySelector('[data-request="'+r.id+'"]')?.scrollIntoView({block:'center'}))},'cw-choice cw-history-result');b.append(el('strong',r.prompt),el('small',new Date(r.created).toLocaleString()));results.append(b)}if(!results.children.length)results.append(el('p','暂无匹配对话'))};search.oninput=paint;paint()}
function toggleHistory(collapsed,persist=true){stage.classList.toggle('history-collapsed',collapsed);versions.hidden=collapsed;historyToggle.setAttribute('aria-label',collapsed?'展开作品层次':'收起作品层次');historyToggle.setAttribute('aria-expanded',String(!collapsed));if(persist&&project)safe(()=>savePatch({historyCollapsed:collapsed}))();requestAnimationFrame(fit)}
async function keepVersion(){if(!project||!current())return;project=await D.keepCanvasVersion(project.id,current().id);render();notify('当前版本已标记保留，所有历史版本均未删除')}
function feedback(kind,source,requestId=null){const p=project;if(!p)return;const versionId=requestId?p.requests.find(r=>r.id===requestId)?.versionId:p.currentVersion;const list=openModal(kind==='positive'?'喜欢这次设计':'意见反馈'),form=el('form'),reason=el('select');reason.setAttribute('aria-label','反馈类型');const options=kind==='positive'?['视觉风格','符合需求','操作体验','其他']:['生成结果不符','文字或排版问题','素材引用问题','操作或保存异常','其他'];options.forEach(s=>reason.add(new Option(s,s)));const details=el('textarea');details.placeholder='请描述你的感受或遇到的问题';details.setAttribute('aria-label','反馈内容');details.maxLength=2000;const note=el('small','反馈仅保存在本机，未发送至客服。'),error=el('p');error.setAttribute('role','alert');const save=button('保存反馈',()=>{},'cw-button primary');save.type='submit';form.append(reason,details,note,error,save);form.onsubmit=async e=>{e.preventDefault();if(!details.value.trim()){error.textContent='请填写反馈内容';details.focus();return}save.disabled=true;try{await D.saveFeedback({kind,source,projectId:p.id,versionId,requestId,reason:reason.value,details:details.value.trim()});modal.close();notify('反馈已保存到本机')}catch(e){error.textContent='保存失败：'+e.message;save.disabled=false}};list.append(form)}
const contextMenu=el('div',undefined,'cw-context-menu');contextMenu.hidden=true;contextMenu.setAttribute('role','menu');document.body.append(contextMenu);
function showContext(e){if(!project)return;e.preventDefault();contextMenu.replaceChildren();const p=project,id=e.target.closest('[data-asset]')?.dataset.asset,record=allSelectable().find(a=>a.id===id);if(record)contextMenu.append(button('保存到素材库',async()=>{contextMenu.hidden=true;await D.saveProjectAssets(p,[record]);notify('已保存到素材库')},'cw-choice','folder-plus'));contextMenu.append(button('意见反馈',()=>{contextMenu.hidden=true;if(project?.id===p.id)feedback('negative','canvas-context')},'cw-choice','message-square'));contextMenu.hidden=false;icons();const r=contextMenu.getBoundingClientRect();contextMenu.style.left=Math.max(8,Math.min(e.clientX,innerWidth-r.width-8))+'px';contextMenu.style.top=Math.max(8,Math.min(e.clientY,innerHeight-r.height-8))+'px';contextMenu.querySelector('button')?.focus()}
stage.addEventListener('contextmenu',showContext);document.addEventListener('pointerdown',e=>{if(!contextMenu.contains(e.target))contextMenu.hidden=true});document.addEventListener('keydown',e=>{if(e.key==='Escape')contextMenu.hidden=true});
const originalRenderLog=renderLog;renderLog=function(){originalRenderLog();[...log.querySelectorAll('.cw-message')].forEach((message,index)=>{const r=project.requests[index],v=project.versions.find(v=>v.id===r.versionId);message.dataset.request=r.id;if(v&&['concept','ready'].includes(v.status)){const controls=el('div',undefined,'cw-feedback');controls.append(ib('点赞反馈','thumbs-up',()=>feedback('positive','chat',r.id)),ib('点踩反馈','thumbs-down',()=>feedback('negative','chat',r.id)));message.append(controls)}});icons()};
const originalRender=render;render=function(){originalRender();toggleHistory(!!project?.historyCollapsed,false);editTools.querySelector('[data-tool=brush]').disabled=current()?.status!=='ready';};
const originalHistory=renderHistory;renderHistory=function(){originalHistory();versions.querySelectorAll('.cw-version').forEach((b,index)=>{if(project.versions[index].kept)b.querySelector('strong')?.append(document.createTextNode(' · 已保留'))})};
const examples=['描述你的设计需求。示例：@素材，为这张照片设计一张海报','使用已选择的 Design System，设计一套产品包装','@素材，保留人物并调整背景和文字排版'];let exampleIndex=0;
setInterval(()=>{if(!input.value&&document.activeElement!==input&&!matchMedia('(prefers-reduced-motion: reduce)').matches)input.placeholder=examples[++exampleIndex%examples.length]},4800);
let mentionEpoch=0;
async function suggestions(target,home){const token=++mentionEpoch,value=home?target.textContent:target.value,match=value.match(/@([^\s，,]*)$/),container=home?homeMention:mention;container.replaceChildren();container.hidden=!match;if(!match)return;const local=home?homeAssets:allSelectable(),records=await preparedAssets(await D.files());if(token!==mentionEpoch)return;const merged=[...local,...records.filter(a=>!local.some(l=>l.id===a.id))],q=match[1].toLowerCase();for(const a of merged.filter(a=>a.name.toLowerCase().includes(q)).slice(0,30)){const b=button('',async()=>{await attach([a],home);const text=value.replace(/@[^\s，,]*$/,'@'+a.name+' ');if(home){target.textContent=text;target.dispatchEvent(new Event('input',{bubbles:true}))}else{target.value=text;await savePatch({draft:text})}container.hidden=true;target.focus()},'cw-choice');if(a.preview)b.append(img(a.preview,a.name));else b.append(icon('file'));b.append(el('span',a.name));container.append(b)}if(!container.children.length)container.append(el('p','暂无可引用素材'));icons()}
const homeMention=el('div',undefined,'cw-mention cw-home-mention');homeMention.hidden=true;$('#create .composer').append(homeMention);
homePrompt.addEventListener('input',()=>safe(()=>suggestions(homePrompt,true))());const oldInput=input.oninput;input.oninput=()=>{oldInput();safe(()=>suggestions(input,false))()};
